def separate_paren_groups(paren_string: str) -> List[str]:
    s = paren_string.replace(" ", "")
    groups = []
    current_depth = 0
    start = 0
    for i, char in enumerate(s):
        if char == '(':
            current_depth += 1
        elif char == ')':
            current_depth -= 1
        if current_depth == 0:
            groups.append(s[start:i+1])
            start = i + 1
    return groups

