import math

def poly(xs: list, x: float):
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    if len(xs) == 2:
        return -xs[0] / xs[1]
    a = -1.0
    b = 1.0
    fa = poly(xs, a)
    fb = poly(xs, b)
    if fa == 0:
        return a
    if fb == 0:
        return b
    while fa * fb >= 0:
        if fa >= 0:
            a *= 2
        else:
            b *= 2
        fa = poly(xs, a)
        fb = poly(xs, b)
        if fa == 0:
            return a
        if fb == 0:
            return b
    while abs(b - a) > 1e-6:
        c = (a + b) / 2.0
        fc = poly(xs, c)
        if fc == 0:
            return c
        if fa * fc < 0:
            b = c
            fb = fc
        else:
            a = c
            fa = fc
    return (a + b) / 2.0

