def intersection(interval1, interval2):
    a1, a2 = interval1
    b1, b2 = interval2
    start = max(a1, b1)
    end = min(a2, b2)
    if start > end:
        return "NO"
    length = end - start
    if length < 2:
        return "NO"
    if length == 2:
        return "YES"
    if length % 2 == 0:
        return "NO"
    i = 3
    while i * i <= length:
        if length % i == 0:
            return "NO"
        i += 2
    return "YES"

