    start_i, start_j = -1, -1
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 1:
                start_i, start_j = i, j
                break
        if start_i != -1:
            break

    path = [1]
    i, j = start_i, start_j
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    for _ in range(k - 1):
        min_val = float('inf')
        next_i, next_j = -1, -1
        for dx, dy in directions:
